      "numero": 1,
      "ar": "المر تِلْكَ ءَايَٰتُ الْكِتَٰبِ وَالَّذِي أُنزِلَ إِلَيْكَ مِن رَّبِّكَ الْحَقُّ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يُؤْمِنُونَ",
