      "ar": "وَهُوَ الَّذِي مَدَّ الْأَرْضَ وَجَعَلَ فِيهَا رَوَٰسِيَ وَأَنْهَٰرًا وَمِن كُلِّ الثَّمَرَٰتِ جَعَلَ فِيهَا زَوْجَيْنِ اثْنَيْنِ يُغْشِي الَّيْلَ النَّهَارَ إِنَّ فِي ذَٰلِكَ لَأيَٰتٍ لِّقَوْمٍ يَتَفَكَّرُونَ",
      "translit": "Wahuwa lladhī madda l-ʾarḍa wajaʿala fīhā rawāsiya waʾanhāran wamin kulli th-thamarāti jaʿala fīhā zawjayni thnayni yughshī llayla n-nahāra inna fī dhālika laʾyātin liqawmin yatafakkarūn",
