    "declic_frequence": "ṭamaʾanna (s'apaiser, se rasséréner, racine ط-م-أ-ن) livre au v.28 le secret de la paix intérieure : a-lā bi-dhikri Llāhi taṭmaʾinnu l-qulūb — « n'est-ce pas par le rappel d'Allah que les cœurs s'apaisent ? » La ṭumaʾnīna, cette quiétude profonde que rien n'ébranle, n'est pas dans les possessions ni les circonstances : elle naît du dhikr, la présence de Dieu à la conscience. Le cœur humain, agité par nature, ne trouve son repos qu'en se souvenant de Celui qui le tient. L'interrogation (a-lā, « n'est-ce pas ») invite chacun à en faire l'expérience."
